<?php
namespace Tests\Unit; use App\Models\TrainingEvaluationQuestion; use App\Services\TrainingEvaluationScoringService; use PHPUnit\Framework\TestCase;
class TrainingEvaluationScoringTest extends TestCase{public function test_percentage_and_rounding():void{$s=new TrainingEvaluationScoringService();$this->assertSame(80.0,$s->calculatePercentage(8,10));$this->assertSame(0.0,$s->calculatePercentage(0,0));$this->assertSame(33.33,$s->calculatePercentage(1,3));}public function test_threshold_is_configurable_and_precise():void{$s=new TrainingEvaluationScoringService();$this->assertSame('failed',$s->determineResult(79.99,80));$this->assertSame('passed',$s->determineResult(80.00,80));$this->assertSame('passed',$s->determineResult(80.01,80));}
 public function test_short_answer_uses_ai_result_when_present():void{$s=new TrainingEvaluationScoringService();$q=new TrainingEvaluationQuestion(['question_type'=>'short_answer','points'=>2]);$result=$s->scoreQuestion($q,[],'EPP',['correct'=>true,'rationale'=>'Coincide con el tema.']);$this->assertTrue($result['correct']);$this->assertSame(2.0,$result['points']);$this->assertTrue($result['countable']);$this->assertFalse($result['pending']);$this->assertSame('Coincide con el tema.',$result['rationale']);}
 public function test_long_answer_counts_points_when_ai_marks_incorrect():void{$s=new TrainingEvaluationScoringService();$q=new TrainingEvaluationQuestion(['question_type'=>'long_answer','points'=>3]);$result=$s->scoreQuestion($q,[],'respuesta fuera de tema',['correct'=>false,'rationale'=>'No es congruente.']);$this->assertFalse($result['correct']);$this->assertSame(0.0,$result['points']);$this->assertTrue($result['countable']);$this->assertFalse($result['pending']);}
 public function test_short_or_long_answer_falls_back_to_pending_without_ai_result():void{$s=new TrainingEvaluationScoringService();$q=new TrainingEvaluationQuestion(['question_type'=>'short_answer','points'=>1]);$result=$s->scoreQuestion($q,[],'respuesta',null);$this->assertNull($result['correct']);$this->assertSame(0.0,$result['points']);$this->assertTrue($result['countable']);$this->assertTrue($result['pending']);}}
